    foreach (a[i]) {
      a[i] inside {[0:999]};
      if (i < n) a[i][0] == 1'b0;     // even
      else       a[i][0] == 1'b1;     // odd
    }
  }
endclass

module tb;
  initial begin
    even_then_odd e = new();
    if (!e.randomize()) $fatal(1, "randomize failed");
    $display("n=%0d a=%p", e.n, e.a);
  end
endmodule
```

