**Mask method**
```systemverilog
class triple_mask;
  rand int a[10];
  rand int repeated;
  rand bit is_rep[10];
  constraint c {
    is_rep.sum() with (int'(item)) == 3;
    foreach (a[i]) {
      if (is_rep[i]) a[i] == repeated; else a[i] != repeated;
      foreach (a[j]) if (i < j && !is_rep[i] && !is_rep[j]) a[i] != a[j];
    }
  }
endclass
```

**Value-table method**
```systemverilog
class triple_table;
  rand int vals[8];               // vals[0] is the tripled value
  rand int sel[10];
  rand int a[10];
  constraint c {
    unique {vals};
    foreach (vals[k]) vals[k] inside {[0:255]};
    foreach (sel[i])  sel[i]  inside {[0:7]};
    sel.sum() with (int'(item == 0)) == 3;
    foreach (vals[k]) if (k > 0) sel.sum() with (int'(item == k)) == 1;
    foreach (a[i]) a[i] == vals[sel[i]];
  }
endclass
```

