```systemverilog
class distinct_window #(int W = 4);
  rand int unsigned value;
  int unsigned hist[$];
  constraint c {
    value inside {[0:15]};
    foreach (hist[i]) value != hist[i];
  }
  function void post_randomize();
    hist.push_back(value);
    if (hist.size() > W - 1) void'(hist.pop_front());
  endfunction
endclass
```

