```systemverilog
class leap_date;
  rand int year, month, day;
  constraint c_year  { year inside {[1900:2400]};
                       (year % 4 == 0) && ((year % 100 != 0) || (year % 400 == 0)); }
  constraint c_month { month inside {[1:12]}; }
  constraint c_day   {
    day >= 1;
    if (month == 2)                    day <= 29;   // leap year, so 29
    else if (month inside {4,6,9,11})  day <= 30;
    else                               day <= 31;
  }
endclass

class power4;
  rand bit [31:0]   value;
  rand int unsigned e;
  constraint c { e inside {[0:15]}; value == (32'd1 << (2 * e)); }
endclass

// Equivalent without an exponent variable
class power4_bits;
  rand bit [31:0] value;
  constraint c {
    value != 0;
    (value & (value - 1)) == 0;          // one-hot
    (value & 32'hAAAA_AAAA) == 0;        // only even bit positions
  }
endclass
```

| value | binary | power of 4? |
| --- | --- | --- |
| 1 | ...0001 | yes (4^0) |
| 16 | ...1_0000 | yes (4^2) |
| 8 | ...1000 | no (odd bit) |
| 12 | ...1100 | no (two bits) |

